select subq_0.c1 as c0, subq_0.c1 as c1, subq_0.c1 as c2, subq_0.c1 as c3, subq_0.c0 as c4, subq_0.c2 as c5, subq_0.c1 as c6, subq_0.c0 as c7 from (select (select id from public.events limit 1 offset 1) as c0, pg_catalog.json_build_array() as c1, pg_catalog.pg_stat_file( cast(sample_0.bio as text), cast(pg_catalog.pg_reload_conf() as bool)) as c2 from public.users as sample_0 tablesample system (7.2) where cast(coalesce(pg_catalog.box( cast(sample_0.coordinates as point)), cast(null as box)) as box) && pg_catalog.box( cast(sample_0.coordinates as point)) limit 106) as subq_0 where pg_catalog.pg_get_wal_replay_pause_state() > pg_catalog.version() limit 78;
